def solve(text):
    if not text.strip(): return []
    out=[]
    for item in text.split(','):
        fields=item.strip().split('..')
        if len(fields)==1: out.append(int(fields[0]))
        elif len(fields)==2:
            a,b=map(int,fields)
            if a>b: raise ValueError('descending')
            out.extend(range(a,b+1))
        else: raise ValueError('malformed')
    return out

escaped-fields:
def solve(text):
    out=[]; current=[]; escaped=False
    for char in text:
        if escaped: current.append(char); escaped=False
        elif char=='\\': escaped=True
        elif char=='|': out.append(''.join(current)); current=[]
        else: current.append(char)
    if escaped: raise ValueError('trailing escape')
    return out+[''.join(current)]

