json-pointer:
import re
def solve(document,pointer):
    if pointer=='': return document
    if not pointer.startswith('/'): raise ValueError('pointer')
    value=document
    for raw in pointer[1:].split('/'):
        if re.search(r'~(?![01])',raw): raise ValueError('escape')
        key=raw.replace('~1','/').replace('~0','~')
        if isinstance(value,dict):
            if key not in value: raise ValueError('missing')
            value=value[key]
        elif isinstance(value,list) and re.fullmatch(r'0|[1-9][0-9]*',key):
            index=int(key)
            if index>=len(value): raise ValueError('index')
            value=value[index]
        else: raise ValueError('traversal')
    return value

